const { Scalekit } = require('@scalekit-sdk/node');
const fs = require('fs');

const envUrl = process.env.SCALEKIT_ENVIRONMENT_URL;
const clientId = process.env.SCALEKIT_CLIENT_ID;
const clientSecret = process.env.SCALEKIT_CLIENT_SECRET;

// Initialize Scalekit
const scalekit = new Scalekit(envUrl, clientId, clientSecret);

// Log the environment URL to output.log
const logPath = '/home/user/scalekit-init/output.log';
fs.writeFileSync(logPath, (envUrl || 'undefined') + '\n');
console.log(`Environment URL logged to ${logPath}`);

